const normalizeSecretsRoot = (value: string): string => value.replace(/\/+$/, "")

const isHelpFlag = (token: string): boolean => token === "--help" || token === "-h"

const helpCommand: Command = { _tag: "Help", message: usageText }
const menuCommand: Command = { _tag: "Menu" }

const parsePort = (value: string): Either.Either<number, ParseError> => {
  const parsed = Number(value)
  if (!Number.isInteger(parsed)) {
    return Either.left({
      _tag: "InvalidOption",
      option: "--ssh-port",
      reason: `expected integer, got: ${value}`
    })
  }
  if (parsed < 1 || parsed > 65535) {
    return Either.left({
      _tag: "InvalidOption",
      option: "--ssh-port",
      reason: "must be between 1 and 65535"
    })
  }
  return Either.right(parsed)
}

const nonEmpty = (
  option: string,
  value: string | undefined,
  fallback?: string
): Either.Either<string, ParseError> => {
  const candidate = value?.trim() ?? fallback
  if (candidate === undefined || candidate.length === 0) {
    return Either.left({
      _tag: "MissingRequiredOption",
      option
    })
  }
  return Either.right(candidate)
}

const buildCreateCommand = (raw: RawOptions): Either.Either<CreateCommand, ParseError> =>
  Either.gen(function* (_) {
    const repoUrl = yield* _(nonEmpty("--repo-url", raw.repoUrl))
    const repoSlug = deriveRepoSlug(repoUrl)
    const derivedContainerName = `dg-${repoSlug}`
