        serviceName,
        sshUser,
        sshPort,
        repoUrl,
        repoRef,
        targetDir,
        volumeName,
        authorizedKeysPath,
        envGlobalPath,
        envProjectPath,
        codexAuthPath,
        codexHome,
        pnpmVersion: defaultTemplateConfig.pnpmVersion
      }
    }
  })

