import { Console, Effect } from "effect"
import * as FileSystem from "@effect/platform/FileSystem"
import * as Path from "@effect/platform/Path"
import type { PlatformError } from "@effect/platform/Error"

import { type CreateCommand } from "../core/domain.js"
import { runDockerComposeUp } from "../shell/docker.js"
import { writeProjectFiles } from "../shell/files.js"

const resolveAuthorizedKeysPath = (
  path: Path.Path,
  baseDir: string,
  authorizedKeysPath: string
): string =>
  path.isAbsolute(authorizedKeysPath)
    ? authorizedKeysPath
    : path.resolve(baseDir, authorizedKeysPath)

const findExistingUpwards = (
  fs: FileSystem.FileSystem,
  path: Path.Path,
  startDir: string,
  fileName: string,
  maxDepth: number
): Effect.Effect<string | null, PlatformError, FileSystem.FileSystem | Path.Path> =>
  Effect.gen(function* (_) {
    let current = startDir
    let depth = 0

    while (true) {
      const candidate = path.join(current, fileName)
      const exists = yield* _(fs.exists(candidate))
      if (exists) {
        return candidate
      }

      const parent = path.dirname(current)
      if (parent === current || depth >= maxDepth) {
        return null
      }

      current = parent
      depth += 1
    }
  })

const findAuthorizedKeysSource = (
  fs: FileSystem.FileSystem,
  path: Path.Path,
  cwd: string
): Effect.Effect<string | null, PlatformError, FileSystem.FileSystem | Path.Path> =>
  Effect.gen(function* (_) {
    const envPath = process.env["DOCKER_GIT_AUTHORIZED_KEYS"]?.trim()
    if (envPath && envPath.length > 0) {
      const exists = yield* _(fs.exists(envPath))
      if (exists) {
        return envPath
      }
    }

    const devKey = yield* _(findExistingUpwards(fs, path, cwd, "dev_ssh_key.pub", 6))
    if (devKey !== null) {
      return devKey
    }

    const authKeys = yield* _(findExistingUpwards(fs, path, cwd, "authorized_keys", 6))
    if (authKeys !== null) {
      return authKeys
    }

    const home = process.env["HOME"]?.trim()
    if (home && home.length > 0) {
      const ed25519 = path.join(home, ".ssh", "id_ed25519.pub")
      const edExists = yield* _(fs.exists(ed25519))
      if (edExists) {
        return ed25519
      }

      const rsa = path.join(home, ".ssh", "id_rsa.pub")
      const rsaExists = yield* _(fs.exists(rsa))
      if (rsaExists) {
        return rsa
      }
    }

    return null
  })

const ensureAuthorizedKeys = (
  baseDir: string,
  authorizedKeysPath: string
): Effect.Effect<void, PlatformError, FileSystem.FileSystem | Path.Path> =>
  Effect.gen(function* (_) {
    const fs = yield* _(FileSystem.FileSystem)
    const path = yield* _(Path.Path)
    const resolved = resolveAuthorizedKeysPath(path, baseDir, authorizedKeysPath)
    const exists = yield* _(fs.exists(resolved))

    if (exists) {
      const info = yield* _(fs.stat(resolved))
      if (info.type === "Directory") {
        const backupPath = `${resolved}.bak-${Date.now()}`
        yield* _(fs.rename(resolved, backupPath))
        yield* _(
          Console.warn(
            `Authorized keys was a directory, moved to ${backupPath}. Creating a file at ${resolved}.`
          )
        )
      } else {
        return
      }
    }

    const source = yield* _(findAuthorizedKeysSource(fs, path, process.cwd()))
    if (source === null) {
      yield* _(
        Console.error(
          `Authorized keys not found. Create ${resolved} with your public key to enable SSH.`
        )
      )
      return
    }

    yield* _(fs.makeDirectory(path.dirname(resolved), { recursive: true }))
    yield* _(fs.copyFile(source, resolved))
    yield* _(Console.log(`Authorized keys copied from ${source} to ${resolved}`))
  })

