type MenuState = {
  readonly cwd: string
  readonly activeDir: string | null
}

type MenuOutcome =
  | { readonly _tag: "Continue"; readonly state: MenuState }
  | { readonly _tag: "Quit" }

const continueWith = (state: MenuState): MenuOutcome => ({ _tag: "Continue", state })

const quitOutcome: MenuOutcome = { _tag: "Quit" }

const renderMenuText = (state: MenuState): string => {
  const activeLine = state.activeDir === null
    ? "Active project: (none)"
    : `Active project: ${state.activeDir}`

  return `docker-git menu
${activeLine}

1) Create project
2) Show connection info
3) docker compose up -d --build
4) docker compose ps
5) docker compose logs --tail=200
6) docker compose down
0) Quit

Select option: `
}

const normalizeYesNo = (input: string): string => input.trim().toLowerCase()

const parseYesDefault = (input: string, fallback: boolean): boolean => {
  const normalized = normalizeYesNo(input)
  if (normalized === "y" || normalized === "yes") {
    return true
  }
  if (normalized === "n" || normalized === "no") {
    return false
  }
  return fallback
}

const resolveAuthorizedKeysPath = (
  path: Path.Path,
  baseDir: string,
  authorizedKeysPath: string
): string =>
  path.isAbsolute(authorizedKeysPath)
    ? authorizedKeysPath
    : path.resolve(baseDir, authorizedKeysPath)

const findExistingUpwards = (
  fs: FileSystem.FileSystem,
  path: Path.Path,
  startDir: string,
  fileName: string,
  maxDepth: number
): Effect.Effect<string | null, PlatformError, FileSystem.FileSystem | Path.Path> =>
  Effect.gen(function* (_) {
    let current = startDir
    let depth = 0

    while (true) {
      const candidate = path.join(current, fileName)
      const exists = yield* _(fs.exists(candidate))
      if (exists) {
        return candidate
      }

      const parent = path.dirname(current)
      if (parent === current || depth >= maxDepth) {
        return null
      }

      current = parent
      depth += 1
    }
  })

const findSshPrivateKey = (
  fs: FileSystem.FileSystem,
  path: Path.Path,
  cwd: string
): Effect.Effect<string | null, PlatformError, FileSystem.FileSystem | Path.Path> =>
  Effect.gen(function* (_) {
    const envKey = process.env["DOCKER_GIT_SSH_KEY"]?.trim()
    if (envKey && envKey.length > 0) {
      const exists = yield* _(fs.exists(envKey))
      if (exists) {
        return envKey
      }
    }

    const devKey = yield* _(findExistingUpwards(fs, path, cwd, "dev_ssh_key", 6))
    if (devKey !== null) {
      return devKey
    }

    const home = process.env["HOME"]?.trim()
    if (home && home.length > 0) {
      const ed25519 = path.join(home, ".ssh", "id_ed25519")
      const edExists = yield* _(fs.exists(ed25519))
      if (edExists) {
        return ed25519
      }

      const rsa = path.join(home, ".ssh", "id_rsa")
      const rsaExists = yield* _(fs.exists(rsa))
      if (rsaExists) {
        return rsa
      }
    }

    return null
  })

const defaultProjectsRoot = (cwd: string): string => {
  const explicit = process.env["DOCKER_GIT_PROJECTS_ROOT"]?.trim()
  if (explicit && explicit.length > 0) {
    return explicit
  }

  return `${cwd}/.docker-git`
}

const isRepoUrlInput = (input: string): boolean => {
  const trimmed = input.trim().toLowerCase()
  return trimmed.startsWith("http://") ||
    trimmed.startsWith("https://") ||
    trimmed.startsWith("ssh://") ||
    trimmed.startsWith("git@")
}

const formatConnectionInfo = (
  cwd: string,
  config: ProjectConfig,
  authorizedKeysPath: string,
  authorizedKeysExists: boolean,
  sshCommand: string
): string =>
  `Project directory: ${cwd}\n` +
  `Container: ${config.template.containerName}\n` +
  `Service: ${config.template.serviceName}\n` +
  `SSH command: ${sshCommand}\n` +
  `Repo: ${config.template.repoUrl} (${config.template.repoRef})\n` +
  `Workspace: ${config.template.targetDir}\n` +
  `Authorized keys: ${authorizedKeysPath}${authorizedKeysExists ? "" : " (missing)"}\n` +
  `Env global: ${config.template.envGlobalPath}\n` +
  `Env project: ${config.template.envProjectPath}\n` +
  `Codex auth: ${config.template.codexAuthPath} -> ${config.template.codexHome}`

const handleMissingConfig = (state: MenuState, error: AppError) =>
  pipe(
    Console.error(renderError(error)),
    Effect.as<MenuOutcome>(continueWith(state))
  )

const withProjectConfig = <R>(
  state: MenuState,
  f: (config: ProjectConfig) => Effect.Effect<void, AppError, R>
) =>
  pipe(
    readProjectConfig(state.activeDir ?? state.cwd),
    Effect.flatMap((config) => pipe(f(config), Effect.as<MenuOutcome>(continueWith(state)))),
    Effect.catchAll((error) =>
      error._tag === "ConfigNotFoundError" || error._tag === "ConfigDecodeError"
        ? handleMissingConfig(state, error)
        : Effect.fail(error)
    )
  )

