  if (!projectId) {
    // no-op
  } else {
    const statusNode = document.querySelector(`[data-deploy-status][data-project-id="${projectId}"]`)
    const messageNode = document.querySelector(`[data-deploy-message][data-project-id="${projectId}"]`)
    const updatedNode = document.querySelector(`[data-deploy-updated][data-project-id="${projectId}"]`)

    const phaseLabels = {
      idle: "idle",
      down: "stopping",
      build: "building",
      up: "starting",
      running: "running",
      error: "error"
    }

    const phaseClasses = {
      idle: "deploy-badge--idle",
      down: "deploy-badge--down",
      build: "deploy-badge--build",
      up: "deploy-badge--up",
      running: "deploy-badge--running",
      error: "deploy-badge--error"
    }

    const applyStatus = (status) => {
      if (!status || typeof status.phase !== "string") {
        return
      }
      const normalized = phaseLabels[status.phase] ? status.phase : "idle"
      if (statusNode) {
        const className = phaseClasses[normalized] ?? phaseClasses.idle
        statusNode.textContent = phaseLabels[normalized] ?? "idle"
        statusNode.className = `deploy-badge ${className}`
      }
      if (messageNode) {
        messageNode.textContent = typeof status.message === "string" ? status.message : ""
      }
      if (updatedNode) {
        updatedNode.textContent = typeof status.updatedAt === "string" ? status.updatedAt : ""
      }
    }

    let autoScroll = true
    logNode.addEventListener("scroll", () => {
      const atBottom = logNode.scrollTop + logNode.clientHeight >= logNode.scrollHeight - 16
      autoScroll = atBottom
    })

    const scrollToTail = () => {
      if (logNode.scrollHeight > logNode.clientHeight + 4) {
        logNode.scrollTop = logNode.scrollHeight
        return
      }
      window.scrollTo(0, document.body.scrollHeight)
    }

    const applyLogs = (entries) => {
      const lines = Array.isArray(entries)
        ? entries
            .filter((entry) => entry && typeof entry.timestamp === "string" && typeof entry.line === "string")
            .map((entry) => `${entry.timestamp} ${entry.line}`)
        : []

      const nextText = lines.length === 0 ? "(no output)" : lines.join("\n")
      if (logNode.textContent !== nextText) {
        logNode.textContent = nextText
      }
      if (autoScroll) {
        scrollToTail()
      }
    }

    const applySnapshot = (payload) => {
      if (!payload || !Array.isArray(payload.entries)) {
        return
      }
      applyLogs(payload.entries)
      applyStatus(payload.status)
    }

    const appendLog = (entry) => {
      if (!entry || typeof entry.timestamp !== "string" || typeof entry.line !== "string") {
        return
      }
      const line = `${entry.timestamp} ${entry.line}`
      if (logNode.textContent === "(no output)" || logNode.textContent.length === 0) {
        logNode.textContent = line
      } else {
        logNode.textContent += `\n${line}`
      }
      if (autoScroll) {
        scrollToTail()
      }
    }

    const startPolling = () => {
      const fetchLogs = () => {
        const request = new XMLHttpRequest()
        request.open("GET", `/api/deployments/${encodeURIComponent(projectId)}/logs`)
        request.responseType = "text"
        request.onload = () => {
          if (request.status < 200 || request.status >= 300) {
            return
          }
          try {
            const payload = JSON.parse(request.responseText)
            applySnapshot(payload)
          } catch {
            // ignore invalid payloads
          }
        }
        request.send()
      }
      fetchLogs()
      setInterval(fetchLogs, 2000)
    }

    if ("EventSource" in window) {
      const source = new EventSource(`/api/deployments/${encodeURIComponent(projectId)}/stream`)
      source.addEventListener("snapshot", (event) => {
        try {
          applySnapshot(JSON.parse(event.data))
        } catch {
          // ignore invalid payloads
        }
      })
      source.addEventListener("log", (event) => {
        try {
          appendLog(JSON.parse(event.data))
        } catch {
          // ignore invalid payloads
        }
      })
      source.addEventListener("status", (event) => {
        try {
          applyStatus(JSON.parse(event.data))
        } catch {
          // ignore invalid payloads
        }
      })
      source.onerror = () => {
        source.close()
        startPolling()
      }
    } else {
      startPolling()
    }
  }
}

