const socket = new WebSocket(socketUrl)

const sendMessage = (payload) => {
  if (socket.readyState === WebSocket.OPEN) {
    socket.send(JSON.stringify(payload))
  }
}

socket.addEventListener("open", () => {
  term.write("Connected.\r\n")
  sendMessage({
    type: "resize",
    cols: term.cols,
    rows: term.rows
  })
