        self.kind = kind
        self.path = path
        self.data = data


def parse_patch(text):
    lines = text.splitlines()
    ops = []
    i = 0
    # skip until Begin Patch
    while i < len(lines) and lines[i].strip() != '*** Begin Patch':
        i += 1
    if i >= len(lines):
        return ops
    i += 1
    while i < len(lines):
        line = lines[i]
        if line.startswith('*** End Patch'):
            break
        if line.startswith('*** Add File: '):
            path = line[len('*** Add File: '):].strip()
            i += 1
            content_lines = []
            while i < len(lines):
                line = lines[i]
                if line.startswith('*** '):
                    break
                if line.startswith('+'):
                    content_lines.append(line[1:])
                else:
                    # unexpected, but include raw
                    content_lines.append(line)
                i += 1
            ops.append(Op('add', path, content_lines))
            continue
        if line.startswith('*** Update File: '):
            path = line[len('*** Update File: '):].strip()
            i += 1
            hunks = []
            current = []
            while i < len(lines):
                line = lines[i]
                if line.startswith('*** '):
                    break
                if line.startswith('@@'):
                    if current:
                        hunks.append(current)
                        current = []
                else:
                    if line.startswith((' ', '+', '-')):
                        current.append(line)
                    else:
                        # treat as context line
                        current.append(' ' + line)
                i += 1
            if current:
                hunks.append(current)
            ops.append(Op('update', path, hunks))
            continue
        if line.startswith('*** Delete File: '):
            path = line[len('*** Delete File: '):].strip()
            ops.append(Op('delete', path, None))
            i += 1
            continue
        # skip unknown
