    # relative to /home/user/docker-git
    return os.path.join('/home/user/docker-git', path)


def apply_update(file_path, hunks):
    if not os.path.exists(file_path):
        # cannot update
        raise FileNotFoundError(file_path)
    with open(file_path,'r',encoding='utf-8') as f:
