            prefix = entry[0]
            line = entry[1:] if prefix in ' +- ' else entry
            if prefix == ' ':
                from_lines.append(line)
                to_lines.append(line)
            elif prefix == '-':
                from_lines.append(line)
            elif prefix == '+':
                to_lines.append(line)
            else:
                # treat as context
                from_lines.append(entry)
                to_lines.append(entry)
        # find from_lines in lines starting at idx
