              pipe(Console.log(usageText), Effect.as<MenuOutcome>(continueWith(state)))),
            Match.when({ _tag: "Menu" }, () => Effect.succeed<MenuOutcome>(continueWith(state))),
            Match.exhaustive
          )
      })
    )
  })

