// CHANGE: orchestrate project creation in the shell layer
// WHY: reuse the same creation flow for CLI and interactive menu
// QUOTE(ТЗ): "Надо написать CLI команду с помощью которой мы будем создавать докер образы"
// REF: user-request-2026-01-07
// SOURCE: n/a
// FORMAT THEOREM: forall cmd: create(cmd) -> files_written(cmd.outDir)
// PURITY: SHELL
// EFFECT: Effect<void, FileExistsError | DockerCommandError | PlatformError, Console | FileSystem | Path | CommandExecutor>
// INVARIANT: docker compose runs only when runUp = true
// COMPLEXITY: O(n) where n = |files|
export const createProject = (command: CreateCommand) =>
  Effect.gen(function* (_) {
    const path = yield* _(Path.Path)
    const resolvedOutDir = path.resolve(command.outDir)
    const createdFiles = yield* _(writeProjectFiles(resolvedOutDir, command.config, command.force))

    yield* _(ensureAuthorizedKeys(resolvedOutDir, command.config.authorizedKeysPath))
    yield* _(ensureEnvFile(resolvedOutDir, command.config.envGlobalPath))
    yield* _(ensureEnvFile(resolvedOutDir, command.config.envProjectPath))
    yield* _(ensureCodexAuthDir(resolvedOutDir, command.config.codexAuthPath))

    yield* _(Console.log(`Created docker-git project in ${resolvedOutDir}`))

    for (const file of createdFiles) {
      yield* _(Console.log(`  - ${file}`))
    }

    if (command.runUp) {
      yield* _(Console.log("Running: docker compose up -d --build"))
      yield* _(runDockerComposeUp(resolvedOutDir))
      yield* _(Console.log("Docker environment is up"))
    }
  })

