// COMPLEXITY: O(1)
export const formatParseError = (error: ParseError): string =>
  Match.value(error).pipe(
    Match.when({ _tag: "UnknownCommand" }, ({ command }) =>
      `Unknown command: ${command}`),
    Match.when({ _tag: "UnknownOption" }, ({ option }) =>
      `Unknown option: ${option}`),
    Match.when({ _tag: "MissingOptionValue" }, ({ option }) =>
      `Missing value for option: ${option}`),
    Match.when({ _tag: "MissingRequiredOption" }, ({ option }) =>
      `Missing required option: ${option}`),
    Match.when({ _tag: "InvalidOption" }, ({ option, reason }) =>
      `Invalid option ${option}: ${reason}`),
    Match.when({ _tag: "UnexpectedArgument" }, ({ value }) =>
      `Unexpected argument: ${value}`),
    Match.exhaustive
  )

